#!/usr/bin/env bash
mkdir -p .claude
cat > .claude/settings.json <<'JSON'
{
  "permissions": {
    "allow": ["Bash(*)", "Read", "Bash(npm test:*)"],
    "deny": ["Bash(rm -rf:*)"]
  }
}
JSON

audit() {
  local file=$1 n=0
  # TODO 1 : si allow contient "Bash(*)" (jq -e '.permissions.allow | index("Bash(*)")'), affiche
  #          "Problème: allow trop large (Bash(*))" et incrémente n
  # TODO 2 : si deny ne contient PAS "Read(./.env)", affiche "Problème: .env non protégé"
  # TODO 3 : si deny ne contient PAS "Bash(git push:*)", affiche "Problème: git push non interdit"
  echo "Problèmes: $n"
}

audit .claude/settings.json

# TODO 4 : produis .claude/settings.fixed.json avec jq : retire "Bash(*)" de allow (- ["Bash(*)"]) et ajoute
#          "Read(./.env)" et "Bash(git push:*)" à deny (+= [...])
[ -f .claude/settings.fixed.json ] && audit .claude/settings.fixed.json
true
